# policy/container_security.rego
package pipeline.container

import future.keywords.if
import future.keywords.in

# Deny containers running as root
deny[msg] if {
  container := input.spec.containers[_]
  not container.securityContext.runAsNonRoot
  msg := sprintf("Container '%v' must set runAsNonRoot: true", [container.name])
}

# Deny use of latest tag
deny[msg] if {
  container := input.spec.containers[_]
  endswith(container.image, ":latest")
  msg := sprintf("Container '%v' uses 'latest' tag — pin to a digest", [container.name])
}

# Deny containers from unapproved registries
approved_registries := {"ghcr.io/myorg", "registry.example.com"}

deny[msg] if {
  container := input.spec.containers[_]
  not any_approved(container.image)
  msg := sprintf("Container '%v' uses unapproved registry", [container.name])
}

any_approved(image) if {
  some registry in approved_registries
  startswith(image, registry)
}
